// Simple Hash Function (DJB2 variant)
        function hashString(str) {
            let hash = 5381;
            for (let i = 0; i < str.length; i++) {
                hash = ((hash << 5) + hash) + str.charCodeAt(i);
            }
            return (hash >>> 0).toString(16);
        }
        // Canvas Fingerprinting Strategy: 
        // We render text and shapes to a hidden canvas. 
        // GPU anti-aliasing and font-smoothing create microscopic byte variations.
        function getCanvasFingerprint() {
            const canvas = document.getElementById('fp-canvas');
            const ctx = canvas.getContext('2d');
            // Clear
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Background
            ctx.fillStyle = "#f60";
            ctx.fillRect(125, 1, 62, 20);
            // Text with different fonts and sizes to trigger sub-pixel offsets
            ctx.textBaseline = "top";
            ctx.font = "16px 'Arial'";
            ctx.fillStyle = "#069";
            ctx.fillText("Fingerprint_v1.0", 2, 2);
            ctx.font = "14px 'Times New Roman'";
            ctx.fillStyle = "rgba(102, 204, 0, 0.7)";
            ctx.fillText("ToolkitGen_Audit", 4, 18);
            // Geometric shapes with alpha transparency
            ctx.strokeStyle = "rgba(102, 0, 204, 0.5)";
            ctx.beginPath();
            ctx.arc(50, 20, 15, 0, Math.PI * 2, true);
            ctx.stroke();
            return canvas.toDataURL();
        }
        function startFingerprinting() {
            const btn = document.getElementById('scan-btn');
            const scanner = document.getElementById('scanner');
            const results = document.getElementById('results-area');
            btn.innerText = "SCANNING HARDWARE...";
            btn.disabled = true;
            results.classList.remove('hidden');
            scanner.style.display = 'block';
            setTimeout(() => {
                // Gather Data Points (Vectors)
                const ua = navigator.userAgent;
                const screenRes = `${window.screen.width}x${window.screen.height}x${window.screen.colorDepth}`;
                const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
                const lang = navigator.language;
                const platform = navigator.platform;
                const canvasData = getCanvasFingerprint();
                // Compute Composite Identifier
                const composite = [ua, screenRes, timezone, lang, platform, canvasData].join(':::');
                const fingerprintID = hashString(composite).toUpperCase();
                // Update UI
                document.getElementById('fingerprint-hash').innerText = fingerprintID;
                document.getElementById('res-ua').innerText = ua;
                document.getElementById('res-screen').innerText = screenRes;
                document.getElementById('res-tz').innerText = timezone;
                document.getElementById('res-lang').innerText = lang;
                document.getElementById('res-platform').innerText = platform;
                document.getElementById('res-canvas').innerText = hashString(canvasData).toUpperCase();
                // Stop Animation
                scanner.style.display = 'none';
                btn.innerText = "RE-GENERATE HASH";
                btn.disabled = false;
                // Smooth Scroll to Results
                results.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }, 2000);
        }
